[
  {
    "statement": "There are currently no studies that have directly evaluated the combined effects of changing both livestock type and grazing season on peatland vegetation.",
    "citations": []
  },
  {
    "statement": "For peatlands specifically, systematic searches found no studies that examined changing livestock type.",
    "citations": [
      "1736"
    ]
  },
  {
    "statement": "For peatlands specifically, systematic searches found no studies that examined changing the grazing season or timing.",
    "citations": [
      "1737"
    ]
  },
  {
    "statement": "Evidence about livestock exclusion effects on peatland vegetation shows no consistent effects on most vegetation groups like cottongrass, sedges and Sphagnum mosses.",
    "citations": [
      "1734"
    ]
  },
  {
    "statement": "Evidence shows that reducing grazing intensity can increase vegetation and shrub cover on peatlands.",
    "citations": [
      "1735"
    ]
  },
  {
    "statement": "No studies have investigated how different livestock species might interact with different grazing seasons to affect peatland vegetation communities.",
    "citations": []
  }
]

[
  {
    "statement": "Research based on available studies shows that repeated burning has measurable effects on plant communities in bogs.",
    "citations": []
  },
  {
    "statement": "In bogs, studies found that increased burning frequency results in higher moss cover, including Sphagnum species.",
    "citations": []
  },
  {
    "statement": "Increased burning frequency in bogs leads to a reduction in heather cover.",
    "citations": []
  },
  {
    "statement": "The effects of burning on herbaceous vegetation have shown mixed results in studies.",
    "citations": []
  },
  {
    "statement": "One study found that burning increased cottongrass cover after a period of 8 to 18 years.",
    "citations": []
  },
  {
    "statement": "Another study found no short-term effects of burning on herbaceous vegetation when measured 2 to 7 months after the event.",
    "citations": []
  },
  {
    "statement": "Burning reduces the cover of purple moor grass.",
    "citations": []
  },
  {
    "statement": "Burning has variable effects on other grass-like plants and forbs.",
    "citations": []
  },
  {
    "statement": "Studies report that plant species richness and diversity may be reduced or limited by burning treatments.",
    "citations": []
  },
  {
    "statement": "No studies have specifically monitored vegetation changes in bogs for 30 years or longer.",
    "citations": []
  },
  {
    "statement": "The longest reported monitoring periods for prescribed fire effects on bog vegetation were up to 20 years.",
    "citations": []
  }
]
